<?php
require_once __DIR__.'/../includes/auth.php';requireActiveUser();requireTenantContext();requireModulePermission('subscriptions','view');global $conn;$tenantId=(int)getCurrentTenantId();$rows=[];
$sql="SELECT a.id,a.account_number,a.username,a.expiry_date,a.status,c.customer_number,c.first_name,c.last_name,p.name plan_name FROM internet_accounts a JOIN customers c ON c.id=a.customer_id AND c.tenant_id=a.tenant_id LEFT JOIN internet_plans p ON p.id=a.plan_id AND p.tenant_id=a.tenant_id WHERE a.tenant_id=? AND a.expiry_date IS NOT NULL AND a.expiry_date BETWEEN CURDATE() AND DATE_ADD(CURDATE(),INTERVAL 30 DAY) ORDER BY a.expiry_date ASC LIMIT 200";
$q=$conn->prepare($sql);if($q){$q->bind_param('i',$tenantId);$q->execute();$z=$q->get_result();while($r=$z->fetch_assoc())$rows[]=$r;$q->close();}
$pageTitle='Expiring Services';require_once __DIR__.'/../includes/header.php';require_once __DIR__.'/../includes/sidebar.php';?>
<div class="main-content"><div class="page-header"><div><h1>Expiring Services</h1><p>Customer services expiring within the next 30 days.</p></div></div><div class="dashboard-card"><div class="table-responsive"><table class="data-table" style="width:100%"><thead><tr><th>Customer</th><th>Account</th><th>Plan</th><th>Expiry</th><th>Days Left</th><th>Status</th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="6">No services are expiring within 30 days.</td></tr><?php else:foreach($rows as $r):?><tr><td><?=e($r['customer_number'].' — '.trim($r['first_name'].' '.$r['last_name']))?></td><td><?=e($r['account_number']??$r['username']??'—')?></td><td><?=e($r['plan_name']??'—')?></td><td><?=e($r['expiry_date'])?></td><td><?=e(max(0,(int)floor((strtotime($r['expiry_date'])-strtotime(date('Y-m-d')))/86400)))?></td><td><?=e(ucfirst($r['status']??''))?></td></tr><?php endforeach;endif;?></tbody></table></div></div></div><?php require_once __DIR__.'/../includes/footer.php';?>